import * as fs from 'fs';
import * as path from 'path';
import { getTitle, parseFrontmatter } from '../utils/markdown-parser';

export { getTitle, parseFrontmatter };

export function generateTemplateList() {
  const baseDir = 'templates';

  const config = {
    outputFile: 'docs/template-list.md',
    title: 'Template List',
    description:
      'This page lists all available Agents, Prompts, and Instructions in this repository. This file is automatically generated.',
    toc: 'Table of Contents',
    globalTitle: 'Global Instructions',
    linkPrefix: '../templates',
  };

  const sections: Record<string, string> = {
    Agents: 'agents',
    Prompts: 'prompts',
    Instructions: 'instructions',
  };

  const outputFilePath = config.outputFile;
  const outputDir = path.dirname(outputFilePath);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  let output = `# ${config.title}\n\n`;
  output += `${config.description}\n\n`;
  output += `## ${config.toc}\n`;
  output += `- [Agents](#agents)\n`;
  output += `- [Prompts](#prompts)\n`;
  output += `- [Instructions](#instructions)\n`;
  output += `- [${config.globalTitle}](#${config.globalTitle.toLowerCase().replace(/\s+/g, '-')})\n\n`;

  for (const [sectionName, folder] of Object.entries(sections)) {
    output += `## ${sectionName}\n\n`;
    output += `| Name | Description | File |\n`;
    output += `| :--- | :--- | :--- |\n`;

    const folderPath = path.join(baseDir, folder);
    if (fs.existsSync(folderPath)) {
      const files = fs.readdirSync(folderPath).sort();
      for (const filename of files) {
        if (!filename.endsWith('.md')) {
          continue;
        }

        const filePath = path.join(folderPath, filename);
        const content = fs.readFileSync(filePath, 'utf8');

        const fm = parseFrontmatter(content);
        const title = fm.name || getTitle(content, filename);
        const description = fm.description || '-';

        const githubLink = `${config.linkPrefix}/${folder}/${filename}`;
        output += `| ${title} | ${description} | [${filename}](${githubLink}) |\n`;
      }
    }
    output += `\n`;
  }

  const globalInstr = path.join(baseDir, 'copilot-instructions.md');
  if (fs.existsSync(globalInstr)) {
    output += `## ${config.globalTitle}\n\n`;
    output += `- [copilot-instructions.md](${config.linkPrefix}/copilot-instructions.md)\n`;
  }

  fs.writeFileSync(outputFilePath, output, 'utf8');
  console.log(`Successfully generated ${outputFilePath}`);
}
